const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a region of interest as a line along the Lower Mississippi River.
  // Using a buffered line to create a polygon for analysis.
  const riverPath = ee.Geometry.LineString([
      [-91.20, 33.60], // Near Arkansas City, AR
      [-90.87, 32.35], // Near Vicksburg, MS
      [-91.40, 31.56]  // Near Natchez, MS
  ]);
  const roi = riverPath.buffer(5000); // Buffer by 5km to capture river meanders

  const date2017 = '2017-03-19';
  const date2019 = '2019-03-19';

  // Function to mask clouds in Sentinel-2 images using the QA60 band.
  function maskS2clouds(image) {
      const qa = image.select('QA60');
      // Bits 10 and 11 are clouds and cirrus, respectively.
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      // Both flags should be set to zero, indicating clear conditions.
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                     .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask).divide(10000)
                  .copyProperties(image, ["system:time_start", "CLOUDY_PIXEL_PERCENTAGE"]);
  }

  // Function to get the best image, calculate NDWI, and identify water pixels.
  function getWaterImage(date, geometry) {
      const startDate = ee.Date(date).advance(-4, 'day');
      const endDate = ee.Date(date).advance(4, 'day');

      let collection = ee.ImageCollection('COPERNICUS/S2_SR')
                         .filterBounds(geometry)
                         .filterDate(startDate, endDate)
                         .sort('CLOUDY_PIXEL_PERCENTAGE');

      if (collection.size().getInfo() === 0) {
        return null; // Return null if no images are found
      }

      const image = ee.Image(collection.first());
      const maskedImage = maskS2clouds(image);

      // Calculate NDWI: (Green - NIR) / (Green + NIR) -> (B3 - B8) / (B3 + B8) for Sentinel-2
      const ndwi = maskedImage.normalizedDifference(['B3', 'B8']).rename('ndwi');
      const water = ndwi.gt(0.1); // Use a threshold to classify water pixels
      return water.selfMask(); // Mask out non-water pixels
  }

  // 2. Data Acquisition & Processing
  const water2017 = getWaterImage(date2017, roi);
  const water2019 = getWaterImage(date2019, roi);

  if (!water2017 || !water2019) {
      console.log(`Image collection for 2017: ${water2017 ? 'Found' : 'Empty'}`);
      console.log(`Image collection for 2019: ${water2019 ? 'Found' : 'Empty'}`);
      console.log('Could not find images for one or both dates.');
      console.log('A');
      return;
  }

  const scale = 1000; // Use a coarse scale to avoid timeout on a large area

  // 3. Calculation
  // Calculate the area of water for each year by summing the pixels.
  // The reducer result will be a dictionary.
  const waterPixels2017 = water2017.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: scale,
      maxPixels: 1e9
  });

  const waterPixels2019 = water2019.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: scale,
      maxPixels: 1e9
  });

  // ee.Dictionary.get() can return null if the band is not found (e.g., all masked)
  const count2017 = waterPixels2017.get('ndwi').getInfo();
  const count2019 = waterPixels2019.get('ndwi').getInfo();

  // 4. Validation & Final Answer
  if (count2017 === null || count2019 === null) {
      console.log(`Valid pixel count 2017: ${count2017}`);
      console.log(`Valid pixel count 2019: ${count2019}`);
      console.log('No valid water pixels found after cloud masking for one or both years.');
      console.log('C2');
      return;
  }

  // Convert pixel counts to area in square kilometers
  const areaPerPixel = (scale * scale) / 1e6; // km^2
  const area2017 = count2017 * areaPerPixel;
  const area2019 = count2019 * areaPerPixel;

  console.log(`2017 Water Pixel Count: ${count2017}`);
  console.log(`2019 Water Pixel Count: ${count2019}`);
  console.log(`2017 Est. Water Area (km^2): ${area2017.toFixed(2)}`);
  console.log(`2019 Est. Water Area (km^2): ${area2019.toFixed(2)}`);

  if (area2019 > area2017) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred:', err.message);
    console.log('D');
});
